class ReactImpl final : public Expression<Expr, Type, TR>, public IV {
public:
    using Expression<Expr, Type, TR>::Expression;

    /**
     * @brief Assign a new value directly to the reactive variable.
     * Only valid for VarExpr + non-const Type.
