    observerA->reset();
    observerB->reset();
    observerC->reset();

    // Step 6: Attempt transactional update that would create cycle
    bool cycleDetected = false;
    try {
        // Try to set up a cycle: A -> B -> C -> A
        graph.addObserver(observerA, observerB);
        graph.addObserver(observerB, observerC);

        // This should throw DependencyCycleException
        graph.addObserver(observerC, observerA);

    } catch (const reaction::DependencyCycleException& e) {
        cycleDetected = true;
        // Step 7: Catch cycle exception if thrown - this is expected
    } catch (const reaction::ReactionException& e) {
        return false; // Unexpected exception
    }

    if (!cycleDetected) {
        return false; // Cycle should have been detected but wasn't
    }

    // Step 8: Notify target again
    observerB->valueChanged(true);

    // Step 9: Verify original relationship is preserved
    // After failed cycle attempt, original A->B relationship should still work
    if (!observerA->wasChanged() || observerA->getCallCount() != 1) {
        return false; // Original relationship not preserved
    }

