 */
template <typename Op, typename L, typename R, IsTrigger TR>
class Expression<CalcExpr, BinaryOpExpr<Op, L, R>, TR>
    : public CalcExprBase<typename BinaryOpExpr<Op, L, R>::value_type, TR> {
