    return g_batch_execute;
}

[[nodiscard]] inline bool isBatchFunctionActive() noexcept {
    return g_batch_fun != nullptr;
}

// === Reset Function ===

inline void resetGlobalState() noexcept {
    g_reg_fun = nullptr;
    g_batch_fun = nullptr;
    g_batch_execute = false;
}

