    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && RightShiftAssignable<Type, U>)
    React &operator>>=(const U &rhs) {
        atomicRightShiftAssign(*getPtr(), rhs);
        return *this;
