    struct StorageInfo {
        bool using_sbo;
        bool initialized;
        size_t type_size;
        size_t stack_usage;
    };

    [[nodiscard]] StorageInfo getStorageInfo() const noexcept {
        return StorageInfo{
            .using_sbo = is_sbo_storage,
            .initialized = is_initialized,
            .type_size = sizeof(Type),
            .stack_usage = is_sbo_storage ? sizeof(Type) : 0
        };
    }

