    template <typename T>
    React &value(T &&t) {
        REACTION_REGISTER_THREAD();
        if (g_batch_fun) {
            std::invoke(g_batch_fun, getPtr());
        } else {
            getPtr()->value(std::forward<T>(t));
        }
        return *this;
    }

