                if (is_initialized && !is_sbo_storage) {
                    // Destroy heap_ptr if it was active from a previous state
                    storage.heap_ptr.~unique_ptr<Type>();
                } else if (!is_initialized) {
                    // First time: destroy the default-constructed heap_ptr
                    storage.heap_ptr.~unique_ptr<Type>();
