            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
            try {
                // Direct access to avoid lock recursion
                if (!is_initialized) {
                    REACTION_THROW_RESOURCE_NOT_INITIALIZED("SBOResource");
