            auto ptr = m_weakPtr.lock();
            if (!ptr) [[unlikely]] {
                REACTION_THROW_NULL_POINTER("weak pointer expired during reset");
            }
            ptr->set(std::forward<F>(f), std::forward<A>(args)...);
        }
