    for (const auto& reactVar : reactSet) {
        orderedNames.push_back(reactVar.getName());
    }

    // 4. Check if all names are unique
    bool allUnique = true;
    if (orderedNames.size() >= 2) {
        for (size_t i = 1; i < orderedNames.size(); ++i) {
