        return static_cast<const Derived *>(this)->evaluate();
    }

    /// @brief Explicit evaluation method for clarity.
    [[nodiscard]] constexpr auto evaluate() const
        noexcept(noexcept(static_cast<const Derived *>(this)->evaluate())) {
        return static_cast<const Derived *>(this)->evaluate();
    }
};

