    using namespace reaction;

    // 1. Create reactive boolean variables
    auto reactiveA = var(a);
    auto reactiveB = var(b);
    auto reactiveC = var(c);

    // 2. Build logical AND expression using operator&&
    auto andExpr = reactiveA && reactiveB;
    auto reactiveAnd = expr(std::move(andExpr));

    // 3. Build logical OR expression using operator||  
    auto orExpr = reactiveA || reactiveC;
    auto reactiveOr = expr(std::move(orExpr));

    // 4. Get initial AND and OR results
    bool initialAnd = reactiveAnd();
    bool initialOr = reactiveOr();

    // 5. Update variables to trigger recomputation
    reactiveA.value(false);
    reactiveB.value(true);
