        auto it = m_cacheEntries.find(key);

        if (it != m_cacheEntries.end() &&
            it->second.version == m_currentVersion.load(std::memory_order_acquire)) {
            // Update last access time (mutable)
            it->second.lastAccess = std::chrono::steady_clock::now();
