     * @brief Sets the actual value directly (only if convertible).
     */
    template <typename T>
        requires(Convertable<T, Type> && IsVarExpr<Expr> && !ConstType<Type>)
    void value(T &&t) {
        this->setValue(std::forward<T>(t));
    }

