    reaction::atomicAddAssign(atomicImpl, 5);

    // 4. Check if add operation reported change
    bool addReportedChange = atomicImpl.lastReportedChange();

    // 5. Apply atomic multiply assignment
    reaction::atomicMultiplyAssign(atomicImpl, 3);

    // 6. Check if multiply operation reported change
    bool multiplyReportedChange = atomicImpl.lastReportedChange();

    // 7. Apply atomic bitwise AND assignment
    reaction::atomicBitwiseAndAssign(atomicImpl, 0x0F);

    // 8. Check if bitwise AND operation reported change
    bool andReportedChange = atomicImpl.lastReportedChange();

    // 9. Apply atomic left shift assignment
    reaction::atomicLeftShiftAssign(atomicImpl, 2);

    // 10. Check if left shift operation reported change
    bool leftShiftReportedChange = atomicImpl.lastReportedChange();

    // 11. Apply atomic increment
    reaction::atomicIncrement(atomicImpl);

    // 12. Check if increment operation reported change
    bool incrementReportedChange = atomicImpl.lastReportedChange();

    // 13. Get final value
    int32_t finalValue = atomicImpl.value();

    // 14. Return atomic helper snapshot
    return AtomicHelperSnapshot{
        finalValue,
        addReportedChange,
        multiplyReportedChange,
        andReportedChange,
        leftShiftReportedChange,
        incrementReportedChange
    };
}

